def get_base7_digits(n):
    digits = []
    temp = n
    while temp > 0:
        digits.append(temp % 7)
        temp //= 7
    return digits

def remove_digit(digits, i):
    # remove the i-th digit (digits[i])
    new_digits = digits[:i] + digits[i+1:]
    val = 0
    for j, d in enumerate(new_digits):
        val += d * (7**j)
    return val

def check_condition(n):
    digits = get_base7_digits(n)
    if not digits:
        return False
    m = len(digits) - 1
    if m == 0:
        return False # positive integer m

    # Try the sum from i=0 to m-1
    sum_a = 0
    for i in range(m):
        sum_a += remove_digit(digits, i)
    if n == sum_a:
        return True, "range(m)"

    # Try the sum from i=0 to m
    sum_a_full = 0
    for i in range(m + 1):
        sum_a_full += remove_digit(digits, i)
    if n == sum_a_full:
        return True, "range(m+1)"

    return False, None

results = []
for n in range(1, 100000):
    res, mode = check_condition(n)
    if res:
        results.append((n, mode))

print(results)

